let product_data = $('Start').first().json.product;

// Беремо і REQUIRED, і RECOMMENDED (IMPORTANT в Adeo-звіті = RECOMMENDED в API)
const allowedLevels = ["REQUIRED", "RECOMMENDED"];

let mandatory_values = $input.first().json.attributes
  .filter(item => allowedLevels.includes(item.requirement_level))
  .map(item => ({
    code: item.code,
    name: item.label,
    description: item.description,
    requirement_level: item.requirement_level,
    value: product_data[item.code] || "",
    type_parameter: item.type_parameter
  }));

return {
  mandatory_values: mandatory_values,
  values_for_ai: mandatory_values.filter(item => item.value === "")
};

// --- Нормалізація output: підтримуємо масив, об'єкт-обгортку {attributes:[]}, об'єкт або JSON-рядок ---
let raw = $json.output;

if (typeof raw === 'string') {
  // Знімаємо markdown-обгортку ```json ... ```
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  try {
    raw = JSON.parse(raw);
  } catch (e) {
    throw new Error(`Не вдалось розпарсити output як JSON: ${e.message}`);
  }
}

// Приводимо до масиву атрибутів
let data;
if (Array.isArray(raw)) {
  // вже масив атрибутів
  data = raw;
} else if (raw && Array.isArray(raw.attributes)) {
  // об'єкт-обгортка { attributes: [...] }
  data = raw.attributes;
} else if (raw && typeof raw === 'object' && raw.code) {
  // один атрибут об'єктом
  data = [raw];
} else {
  data = [];
}

// --- Мапа requirement_level з попереднього кроку ---
const origMap = {};
($('search need REQUIRED atributes').first().json.values_for_ai || []).forEach(i => {
  origMap[i.code] = i.requirement_level;
});

const atributesFromAI = [];
const error = [];

data.forEach(i => {
  const item = {
    code: i.code,
    value: i.value,
    type_parameter: i.type_parameter
  };

  // Помилкою вважаємо лише порожнє REQUIRED. Для RECOMMENDED порожнє значення — OK.
  if (!i.value && origMap[i.code] === "REQUIRED") {
    error.push(item);
  }

  // У продукт пишемо тільки непорожні значення
  if (i.value) atributesFromAI.push(item);
});

return { atributesFromAI, error };

const values_for_ai = $input.first().json.values_for_ai || [];

// Перевірено в Adeo:
//   type_parameter = "ATT_10837"           -> /api/values_lists?code=ATT_10837            OK
//   type_parameter = "MOD_201057_ATT_22088"-> /api/values_lists?code=MOD_201057_ATT_22088 OK
//   type_parameter = "1024"                -> 404 (це код типу "Image URL", не values_list)
//   type_parameter = "3"                   -> загальний текстовий тип, пропускаємо
//
// Логіка фільтру: лишаємо атрибути, які МОЖУТЬ мати values_list.
// Це ATT_* і MOD_*_ATT_* (завжди есть список). Все інше (числові коди типу 1024,
// "3", null, порожнє) — відкидаємо. Додатково виключаємо media_* (картинки/відео).

const filtered = values_for_ai.filter(item => {
  const tp = item.type_parameter;
  if (tp === null || tp === undefined || tp === "") return false;
  if (tp === "3") return false;

  const code = String(item.code || "");
  if (code.startsWith("media_")) return false;

  const tpStr = String(tp);
  // Пропускаємо тільки ті type_parameter, що мають values_list у Adeo.
  if (tpStr.startsWith("ATT_") || tpStr.startsWith("MOD_")) return true;

  // Числові (1024 тощо) — це не values_list id, відкидаємо.
  return false;
});

return filtered;

const input = $input.first().json;

const result = (input.values_lists || []).map(list => ({
  code: list.code,
  label: list.label,
  values: (list.values || []).map(v => ({
    value: v.label
  }))
}));

// Тепер обертаємо результат у масив з ключем = code першого елемента values_lists
const wrapped = {
  [input.values_lists[0].label]: result
};

// Повертаємо як масив з одним об'єктом для n8n
return [{ json: wrapped }];
